--
-- Name: text_array_to_string_immutable(text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.text_array_to_string_immutable(input text[], delim text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT array_to_string(input, delim);
$$;


--
-- Name: uuid_array_has_unique_elements(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uuid_array_has_unique_elements(input uuid[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT cardinality(input) = (SELECT count(DISTINCT value) FROM unnest(input) AS value);
$$;


