d50294f7-2159-43ea-b1bc-78d6ca39b634	70000000-0000-4000-8000-000000000010	80000000-0000-4000-8000-000000000003	00000000-0000-4000-8000-000000000001	0	Research Title: Decentralized Microgrid Optimization for Rural Electrification in East Africa\n\nAbstract: This doctoral dissertation develops a comprehensive mathematical framework and metaheuristic optimization algorithms for autonomous solar photovoltaic and battery storage microgrids. Field validations across rural Ethiopian communities show a 34% cost reduction over traditional diesel generators.\n\nKeywords: microgrids, renewable-energy, optimization, rural-electrification, solar-pv	489	1	22b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b222	{"title": "Decentralized Microgrid Optimization for Rural Electrification in East Africa", "version": "22b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b222", "char_end": 490, "char_start": 0, "research_id": "80000000-0000-4000-8000-000000000003", "resource_id": "70000000-0000-4000-8000-000000000010", "resource_type": "research", "institution_id": "00000000-0000-4000-8000-000000000001", "institution_name": "Addis Ababa University"}	[0.3265541,1.0165051,-3.444856,-0.2513291,0.96465236,-0.8400616,0.40050924,-0.0348107,-1.2070211,0.8420704,0.51732576,-0.30800778,1.4532509,0.6842551,0.115933836,1.0946573,-0.725013,0.035533637,-0.2461082,0.6484812,-0.41376793,-0.012312824,-0.020842876,0.36375475,1.7478958,0.61977917,-0.024080371,-0.71095407,0.69265246,-0.6330943,0.43299747,-1.0066792,0.062706046,0.0652045,-1.983167,-0.1690274,1.6889185,-0.55783147,0.5072135,0.12294223,0.071965866,0.3890238,-0.13731842,0.21989416,1.6288142,0.1255719,1.7321236,-0.5637371,0.792727,-1.3165383,0.40910596,1.1361148,0.7410985,-0.44607002,0.041427165,-1.2361034,-0.5982283,0.3949995,-0.6460326,-0.24277945,1.8212328,1.9858357,-1.0560108,0.4259994,0.85195744,-0.6972377,-0.45870072,-0.1131945,-0.6196529,-1.0307786,0.7796904,-0.6976992,0.33821163,0.2368456,0.8735243,-0.11923621,-0.3303664