6c1b6689-6516-426c-b7e5-53aa22e341d6	70000000-0000-4000-8000-000000000011	80000000-0000-4000-8000-000000000004	00000000-0000-4000-8000-000000000001	0	Research Title: Scalable Cloud Architecture for Digital Academic Registries in Developing Countries\n\nAbstract: Higher education institutions in developing regions frequently face severe bandwidth constraints. We propose a lightweight, distributed multi-tenant database synchronization protocol designed for academic student registries, providing resilient offline-first capabilities.\n\nConference: IEEE International Conference on Educational Technologies 2026	459	1	11b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b111	{"title": "Scalable Cloud Architecture for Digital Academic Registries in Developing Countries", "version": "11b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b111", "char_end": 460, "char_start": 0, "research_id": "80000000-0000-4000-8000-000000000004", "resource_id": "70000000-0000-4000-8000-000000000011", "resource_type": "research", "institution_id": "00000000-0000-4000-8000-000000000001", "institution_name": "Addis Ababa University"}	[-0.42429453,1.0818529,-3.8812852,-0.7621947,0.866857,0.056075875,1.1682597,0.30904174,-0.08208287,0.19436942,0.17426461,0.099868,1.7721238,-0.65978926,-0.29084435,0.11799406,-0.7029578,-0.23750311,-1.0857879,0.2440928,-0.7190725,-0.75672656,-0.9965356,-0.18619679,0.91990864,0.8883853,0.25001812,-0.70690835,-0.6613909,-0.089752495,0.5776358,-0.5548209,-0.43223634,-0.07214787,-0.2742436,0.07338569,-0.5134358,-1.3414295,-0.2615709,0.6086504,0.917156,-0.68772084,0.20868964,-0.6877864,0.6629063,0.96013474,1.1002345,-0.434379,1.8463143,-1.1294214,0.17612709,0.23187064,0.20127594,0.17051008,-0.2558161,0.1426891,-0.74744093,1.0512921,-0.79343855,-0.506851,2.434668,1.3576906,-0.6850538,0.9933055,1.4770035,0.17956676,-0.61679006,0.46986517,0.028265875,-1.0662416,0.7362174,-0.33649498,0.5584527,0.12367865,0.36004636,-0.59643763,-0.480369,-1.1282697,-0.21742226