2eb5e0bf-df16-4c1d-b70c-02a3881b1210	70000000-0000-4000-8000-000000000009	80000000-0000-4000-8000-000000000002	00000000-0000-4000-8000-000000000002	0	Research Title: Automated Crop Disease Detection Using Convolutional Neural Networks in Ethiopian Agriculture\n\nAbstract: This master's thesis investigates the application of convolutional neural networks (CNNs) for real-time mobile diagnosis of foliar diseases in coffee and teff crops in Northern and Western Ethiopia. Field-tested with 12,000 leaf images, the proposed model runs efficiently on edge mobile devices.\n\nKeywords: computer-vision, crop-disease, agriculture, cnn, coffee-leaf-rust	494	1	33b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b333	{"title": "Automated Crop Disease Detection Using Convolutional Neural Networks in Ethiopian Agriculture", "version": "33b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b333", "char_end": 495, "char_start": 0, "research_id": "80000000-0000-4000-8000-000000000002", "resource_id": "70000000-0000-4000-8000-000000000009", "resource_type": "research", "institution_id": "00000000-0000-4000-8000-000000000002", "institution_name": "Bahir Dar University"}	[0.8601404,0.27040604,-4.0791187,-0.70537555,1.2355099,-0.54464126,0.4845186,-0.09187837,-0.65578157,0.14674844,0.7514737,0.11181917,2.6042755,0.33467075,-0.6609569,0.13879234,-1.7894362,-0.034794953,-0.6590903,0.04630836,0.23831388,1.4156331,0.17311625,0.18747194,0.89719707,0.6737398,-1.081842,0.55803484,0.099293105,-0.2389027,0.91939294,-1.3835622,-1.1203238,-0.52256304,-0.8406649,-0.17272416,1.2511674,-0.7143527,0.89970374,1.041943,0.7490103,-0.33702996,-0.1687666,-0.6139134,0.59001434,1.2080568,1.07382,0.7562602,1.3921041,-1.2766075,0.12630808,0.837141,0.12941882,-0.6523618,0.62871987,-0.0043729236,-0.16265507,1.0046988,-0.6833179,-1.0522215,2.2394705,2.0447445,-0.9474442,0.76935804,0.6664694,-0.30974746,-0.29471695,0.15487178,-0.43128386,-1.0855867,0.10937349,-1.0371044,0.7094911,0.83187765,0.4676454,-0