cb56a2b3-7b63-4455-ab79-9a979843d89c	70000000-0000-4000-8000-000000000008	80000000-0000-4000-8000-000000000001	00000000-0000-4000-8000-000000000001	0	Research Title: Deep Learning for Amharic Natural Language Processing: A Benchmark Study\n\nAbstract: We present a comprehensive empirical benchmark of modern deep learning architectures applied to Amharic natural language processing. Using curated corpora from news archives and social discourse, our transformer models achieve state-of-the-art results across text classification, named entity recognition, and question answering.\n\nJournal: Ethiopian Journal of Science and Computing	482	1	44b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b444	{"title": "Deep Learning for Amharic Natural Language Processing: A Benchmark Study", "version": "44b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b444", "char_end": 483, "char_start": 0, "research_id": "80000000-0000-4000-8000-000000000001", "resource_id": "70000000-0000-4000-8000-000000000008", "resource_type": "research", "institution_id": "00000000-0000-4000-8000-000000000001", "institution_name": "Addis Ababa University"}	[-0.005271609,0.27377927,-2.618174,-2.0929408,1.4060407,-0.18739924,0.006152549,0.32316783,-1.2325661,0.7506412,0.031575114,0.40705693,1.9853283,0.4861972,0.13908534,-0.6315592,-0.26134425,-0.5326585,-0.7950299,0.814313,-1.0597647,0.7900534,0.9415506,0.39277044,1.5469604,-0.16845702,-0.7464564,-0.46142027,-0.52780646,0.4034026,0.500271,-1.0232881,-0.59666264,0.2608158,-0.6403219,-0.85155255,1.050045,-0.62494653,-0.060444456,0.70834094,0.62658525,0.21324396,-0.5197798,-0.133561,1.2780243,0.0034894971,0.7776522,-0.39751562,1.4308978,-2.0638597,0.2908902,0.54187757,0.7350598,-0.1404904,0.9624935,-0.45351446,-0.92742395,0.812498,-0.96968555,-0.79767245,1.9120213,1.6155682,-1.5013559,1.0042461,0.38356802,0.28288043,-0.11656747,1.340335,-0.4521229,-0.5255698,0.5784772,-0.4204287,-0.4604959,1.510711,-0.15331873,-0.67528933,-0.063124895,-0.590122